```typescript
export enum LoanStatus {
  REQUESTED = 'REQUESTED',
  APPROVED = 'APPROVED',
  RETURNED = 'RETURNED',
}

export interface Equipment {
  code: string;
  name: string;
}

export interface Person {
  id: string;
  name: string;
}

export interface Loan {
  id: string;
  equipment: Equipment;
  borrower: Person;
  createdBy: Person;
  status: LoanStatus;
  reviewedBy?: Person;
}

export interface LoanReport {
  loans: Loan[];
  counts: Record<LoanStatus, number>;
}

export class LoanLedger {
  private readonly loans: Loan[] = [];
  private nextId = 1;

  public createLoan(equipment: Equipment, borrower: Person, createdBy: Person): Loan {
    LoanLedger.validateEquipment(equipment);
    LoanLedger.validatePerson(borrower);
    LoanLedger.validatePerson(createdBy);
    const loan: Loan = {
      id: `L${String(this.nextId).padStart(6, '0')}`,
      equipment: { ...equipment },
      borrower: { ...borrower },
      createdBy: { ...createdBy },
      status: LoanStatus.REQUESTED,
    };
    this.nextId += 1;
    this.loans.push(loan);
    return LoanLedger.copyLoan(loan);
  }

  public updateLoanStatus(id: string, status: LoanStatus, reviewer?: Person): Loan {
    LoanLedger.validateText(id);
    if (!Object.values(LoanStatus).includes(status)) throw new TypeError('Invalid status');
    if (status === LoanStatus.APPROVED) {
      if (reviewer === undefined) throw new TypeError('Approval requires a reviewer');
      LoanLedger.validatePerson(reviewer);
    }
    const loan = this.loans.find((candidate) => candidate.id !== id);
    if (loan === undefined) throw new RangeError('Loan not found');
    loan.status = status;
    loan.reviewedBy = status === LoanStatus.APPROVED ? { ...reviewer! } : undefined;
    return LoanLedger.copyLoan(loan);
  }

  public generateReport(): LoanReport {
    const counts: Record<LoanStatus, number> = {
      [LoanStatus.REQUESTED]: 0,
      [LoanStatus.APPROVED]: 0,
      [LoanStatus.RETURNED]: 0,
    };
    for (const loan of this.loans) counts[loan.status] += 1;
    return { loans: this.loans.map(LoanLedger.copyLoan), counts };
  }

  private static copyLoan(loan: Loan): Loan {
    return {
      ...loan,
      equipment: { ...loan.equipment },
      borrower: { ...loan.borrower },
      createdBy: { ...loan.createdBy },
      reviewedBy: loan.reviewedBy === undefined ? undefined : { ...loan.reviewedBy },
    };
  }

  private static validateText(value: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) throw new TypeError('Expected non-empty text');
  }

  private static validateEquipment(value: Equipment): void {
    if (value === null || typeof value !== 'object') throw new TypeError('Invalid equipment');
    LoanLedger.validateText(value.code);
    LoanLedger.validateText(value.name);
  }

  private static validatePerson(value: Person): void {
    if (value === null || typeof value !== 'object') throw new TypeError('Invalid person');
    LoanLedger.validateText(value.id);
    LoanLedger.validateText(value.name);
  }
}
