import { LoanLedger, LoanStatus } from './solution';
import type { Equipment, Person } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => void, ctor: Function, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof (ctor as new (...args: never[]) => Error), message);
}

const ledger = new LoanLedger();
const equipment: Equipment = { code: 'EQ-1', name: 'Camera' };
const borrower: Person = { id: 'P-1', name: 'Borrower' };
const creator: Person = { id: 'P-2', name: 'Creator' };
const first = ledger.createLoan(equipment, borrower, creator);
equal(first.id, 'L000001', 'first sequential ID');
equal(first.status, LoanStatus.REQUESTED, 'initial status');
equipment.name = 'mutated equipment';
borrower.name = 'mutated borrower';
creator.name = 'mutated creator';
first.equipment.name = 'mutated return';
const second = ledger.createLoan(
  { code: 'EQ-2', name: 'Laptop' },
  { id: 'P-3', name: 'Second borrower' },
  { id: 'P-4', name: 'Second creator' },
);
equal(second.id, 'L000002', 'second sequential ID');

const reportBefore = ledger.generateReport();
equal(reportBefore.loans[0].equipment.name, 'Camera', 'create input and return are isolated');
equal(reportBefore.loans[0].borrower.name, 'Borrower', 'borrower copied');
equal(reportBefore.loans[0].createdBy.name, 'Creator', 'creator copied');
equal(reportBefore.loans[1].id, 'L000002', 'creation order preserved');
equal(reportBefore.counts[LoanStatus.REQUESTED], 2, 'requested count');

const reviewer: Person = { id: 'R-1', name: 'Reviewer' };
const approved = ledger.updateLoanStatus('L000002', LoanStatus.APPROVED, reviewer);
equal(approved.id, 'L000002', 'exact matching loan updated');
equal(approved.status, LoanStatus.APPROVED, 'approved status');
equal(approved.reviewedBy?.name, 'Reviewer', 'reviewer stored');
reviewer.name = 'mutated reviewer';
if (approved.reviewedBy !== undefined) approved.reviewedBy.name = 'mutated result';
equal(ledger.generateReport().loans[1].reviewedBy?.name, 'Reviewer', 'reviewer input and result copied');
equal(ledger.generateReport().loans[0].status, LoanStatus.REQUESTED, 'other loan unchanged');

const returned = ledger.updateLoanStatus('L000002', LoanStatus.RETURNED, { id: 'ignored', name: 'Ignored' });
equal(returned.status, LoanStatus.RETURNED, 'returned status');
equal(returned.reviewedBy, undefined, 'non-approved status clears reviewer');

throws(() => ledger.updateLoanStatus('L000001', LoanStatus.APPROVED), TypeError, 'approval requires reviewer');
equal(ledger.generateReport().loans[0].status, LoanStatus.REQUESTED, 'failed approval does not mutate');
throws(() => ledger.updateLoanStatus('L999999', LoanStatus.RETURNED), RangeError, 'missing ID');
throws(() => ledger.updateLoanStatus(' L000001 ', LoanStatus.RETURNED), RangeError, 'ID matching is exact');
throws(() => ledger.updateLoanStatus('L000001', 'BAD' as LoanStatus), TypeError, 'invalid status');
throws(() => ledger.createLoan({ code: '', name: 'bad' }, { id: 'x', name: 'x' }, { id: 'y', name: 'y' }), TypeError, 'invalid creation data');
equal(ledger.generateReport().loans.length, 2, 'failed operations add no loans');

const finalReport = ledger.generateReport();
equal(finalReport.counts[LoanStatus.REQUESTED], 1, 'final requested count');
equal(finalReport.counts[LoanStatus.APPROVED], 0, 'final approved count');
equal(finalReport.counts[LoanStatus.RETURNED], 1, 'final returned count');
finalReport.loans[0].borrower.name = 'report mutation';
finalReport.counts[LoanStatus.REQUESTED] = 99;
const freshReport = ledger.generateReport();
equal(freshReport.loans[0].borrower.name, 'Borrower', 'report loans are copied');
equal(freshReport.counts[LoanStatus.REQUESTED], 1, 'report counts are fresh');

